def min_cost_connect_points(points):
    edges = []
    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            dist = abs(points[i][0] - points[j][0]) + abs(points[i][1] - points[j][1])
            edges.append((dist, i, j))
    return kruskal(edges)

