import heapq

def prim(graph):
    mst = []
    visited = set()
    min_heap = [(0, 0)]  # (weight, vertex)
    while min_heap:
        weight, u = heapq.heappop(min_heap)
        if u not in visited:
            visited.add(u)
            mst.append((weight, u))
            for v in graph[u]:
                heapq.heappush(min_heap, (weight, v))
    return mst

